import{Tt as e,at as t,rt as n,t as r}from"./chunks/framework.CZq4qJDD.js";var i=JSON.parse(`{"title":"Tooling with mise","description":"","frontmatter":{"title":"Tooling with mise","authorship":["ai"]},"headers":[],"relativePath":"developer/mise.md","filePath":"developer/mise.md"}`),a={name:`developer/mise.md`};function o(r,i,a,o,s,c){return e(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795432063000`},[...i[0]||=[t(`<h1 id="tooling-with-mise" tabindex="-1">Tooling with mise <a class="header-anchor" href="#tooling-with-mise" aria-label="Permalink to “Tooling with mise”">​</a></h1><p><a href="https://mise.jdx.dev" target="_blank" rel="noreferrer">mise</a> pins every CLI tool the repository needs (codegen, Helm, Go, Node, linters, …) for both local development and CI. Versions are locked with <a href="https://mise.jdx.dev/dev-tools/mise-lock.html" target="_blank" rel="noreferrer"><code>mise.lock</code></a> so every machine installs the same binaries, verified by checksum.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><p>Local development and CI need different tools, so the config is split with <a href="https://mise.jdx.dev/configuration/environments.html" target="_blank" rel="noreferrer">config environments</a>. Each config file has its own lockfile next to it.</p><table tabindex="0"><thead><tr><th>File</th><th>Lockfile</th><th>Holds</th><th>Loaded</th></tr></thead><tbody><tr><td><code>mise.toml</code></td><td><code>mise.lock</code></td><td>Tools and env shared by local and CI</td><td>Always</td></tr><tr><td><code>mise.dev.toml</code></td><td><code>mise.dev.lock</code></td><td>Local-only tools and env (pnpm, delve, stripe, …)</td><td>Locally, the default environment</td></tr><tr><td><code>mise.ci.toml</code></td><td><code>mise.ci.lock</code></td><td>CI-only tools (just, codecov, python, uv, …)</td><td>In CI, with <code>MISE_ENV=ci</code></td></tr><tr><td><code>.miserc.toml</code></td><td></td><td>Selects <code>dev</code> by default, ignores <code>.tool-versions</code></td><td>Read before every other file</td></tr><tr><td><code>.mise/locks/</code></td><td></td><td>Dependency graphs of <code>npm:</code> and <code>pipx:</code> tools</td><td>Committed with the lockfiles</td></tr></tbody></table><p><code>MISE_ENV=ci</code> replaces the <code>.miserc.toml</code> default rather than adding to it, so CI never loads <code>mise.dev.toml</code> and local machines never load <code>mise.ci.toml</code>.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> config</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ls</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">            # mise.toml + mise.dev.toml</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -E</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ci</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> config</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ls</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">      # mise.toml + mise.ci.toml</span></span></code></pre></div><p><code>.tool-versions</code> is not read by mise. It only feeds <code>actions/setup-go</code> and <code>golangci-lint-action</code> in CI, so keep its <code>golang</code> version equal to <code>go</code> in <code>mise.toml</code>.</p><p>Project settings in <code>mise.toml</code> that keep the lockfiles reproducible:</p><ul><li><code>min_version</code>: lockfiles written by older mise versions are rejected by newer ones (missing checksums), so everyone runs at least the version CI pins in <code>.github/actions/setup/action.yml</code>.</li><li><code>lockfile = true</code>: <code>mise use</code> and <code>mise upgrade</code> keep the lockfiles in sync.</li><li><code>[tool_config] locked = true</code>: installing a project tool without a lock entry fails, but your global tools in <code>~/.config/mise</code> keep their own policy.</li><li><code>npm.package_manager = &quot;aube&quot;</code>: the <code>npm:</code> dependency graphs do not depend on a personal global <code>npm.package_manager</code> setting.</li></ul><h2 id="first-setup" tabindex="-1">First setup <a class="header-anchor" href="#first-setup" aria-label="Permalink to “First setup”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> self-update</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">   # if mise reports a too-old version</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> trust</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> install</span></span></code></pre></div><h2 id="adding-or-changing-a-tool" tabindex="-1">Adding or changing a tool <a class="header-anchor" href="#adding-or-changing-a-tool" aria-label="Permalink to “Adding or changing a tool”">​</a></h2><p>Pick the file with <code>--env</code>. Without it, <code>mise use</code> writes to the shared <code>mise.toml</code>.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> use</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> helm@4.3.2</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">                  # local and CI   -&gt; mise.toml,     mise.lock</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> use</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --env</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> dev</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> stripe@latest</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">     # local only     -&gt; mise.dev.toml, mise.dev.lock</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> use</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --env</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ci</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> uv@0.13.9</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">          # CI only        -&gt; mise.ci.toml,  mise.ci.lock</span></span></code></pre></div><p>To move a tool between scopes, move its line by hand, then refresh the lockfiles.</p><h2 id="refreshing-and-bumping-lockfiles" tabindex="-1">Refreshing and bumping lockfiles <a class="header-anchor" href="#refreshing-and-bumping-lockfiles" aria-label="Permalink to “Refreshing and bumping lockfiles”">​</a></h2><p>Lockfiles cover <code>linux-x64</code> (CI, WSL) and <code>macos-arm64</code>. <code>mise lock</code> keeps the platforms that are already recorded, so pass <code>--platform</code> only to add one.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &amp;&amp;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -E</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ci</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;">               # refresh after editing a toml by hand</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --bump</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &amp;&amp;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -E</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ci</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --bump</span><span style="--shiki-light:#7C7F93;--shiki-light-font-style:italic;--shiki-dark:#9399B2;--shiki-dark-font-style:italic;"> # move \`latest\` / prefix requests to newer versions</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> install</span></span></code></pre></div><p><code>--bump</code> does not change exact pins such as <code>helm = &quot;4.3.2&quot;</code>; use <code>mise upgrade --bump helm</code> for those. Running <code>mise -E ci lock</code> installs nothing, it only resolves and writes <code>mise.ci.lock</code>.</p><h2 id="before-committing" tabindex="-1">Before committing <a class="header-anchor" href="#before-committing" aria-label="Permalink to “Before committing”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --check</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &amp;&amp;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -E</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ci</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --check</span></span></code></pre></div><p>Commit the changed <code>mise*.toml</code>, <code>mise*.lock</code> and <code>.mise/locks/</code> files together. Personal overrides go to <code>mise.local.toml</code> or <code>mise.dev.local.toml</code>, which are gitignored with their lockfiles.</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to “CI”">​</a></h2><p><code>.github/workflows/ci.yaml</code> sets <code>MISE_ENV=ci</code>. The setup action pins the mise version, runs <code>jdx/mise-action</code> (which installs with <code>mise install --locked</code> because <code>mise.lock</code> exists) and then checks that all lockfiles are up to date:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --check</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &amp;&amp;</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> mise</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -E</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> dev</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> lock</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --check</span></span></code></pre></div><p>A pull request that edits a <code>mise*.toml</code> without refreshing its lockfile fails that step. Changes to only <code>mise.dev.toml</code>, <code>mise.dev.lock</code> or <code>.mise/locks/mise.dev/</code> do not trigger CI.</p><h2 id="upgrading-mise" tabindex="-1">Upgrading mise <a class="header-anchor" href="#upgrading-mise" aria-label="Permalink to “Upgrading mise”">​</a></h2><p>Bump <code>min_version</code> in <code>mise.toml</code> and <code>version</code> of <code>jdx/mise-action</code> in <code>.github/actions/setup/action.yml</code> together, then refresh the lockfiles with the new version.</p><h2 id="renovate" tabindex="-1">Renovate <a class="header-anchor" href="#renovate" aria-label="Permalink to “Renovate”">​</a></h2><p>Renovate&#39;s mise manager reads <code>mise.toml</code>, <code>mise.dev.toml</code> and <code>mise.ci.toml</code> and updates the matching lockfiles and sidecars in the same pull request. If an update arrives without its lockfile, the CI lockfile check fails; run the refresh commands above on that branch.</p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};